definition.script:
pipeline {
    agent any

    environment {
        DOCKER_REGISTRY = 'docker.io'
        DOCKER_IMAGE_NAME = 'samruddhinikhare/skillpilots-backend'
        DOCKER_TAG = "${env.BUILD_NUMBER}"

        ARTIFACT_NAME = 'skillpilots.war'
        ARTIFACT_PATH = "target/${ARTIFACT_NAME}"
        CONTAINER_NAME = 'springboot-war-app'
        PORT_MAPPING = '8001:8001'
    }

    stages {
        stage('Checkout') {
            steps {
                git(
                    branch: 'shanku',
                    url: 'https://github.com/Samruddhikumbhare/skillpilots_new_war.git'
                )
            }
        }

        stage('Build') {
            steps {
                sh '''
                   chmod +x mvnw
                   ./mvnw clean package
               '''
            }
        }

        stage('Verify Artifact') {
            steps {
                sh '''
                    echo "Generated WAR file:"
                    ls -la ${ARTIFACT_PATH}
                '''
            }
        }

        stage('Build Docker Image') {
            steps {
                script {
                    sh 'ls -la Dockerfile'

                    sh """
                        DOCKER_BUILDKIT=0 docker build \
                        -t ${DOCKER_IMAGE_NAME}:${DOCKER_TAG} \
                        --build-arg WAR_FILE=${ARTIFACT_PATH} \
                        -f Dockerfile .
                    """
                }
            }
        }

        stage('Deploy') {
            steps {
                script {
                    sh """
                        docker stop ${CONTAINER_NAME} || true
                        docker rm ${CONTAINER_NAME} || true
                    """

                    sh """
                        docker run -d \
                            --name ${CONTAINER_NAME} \
                            -p ${PORT_MAPPING} \
                            --restart unless-stopped \
                            ${DOCKER_IMAGE_NAME}:${DOCKER_TAG}
                    """
                }
            }
        }
    }

    post {
        always {
            cleanWs()
            sh 'docker system prune -f'
        }
    }
}
